        pdirs = [(-1,-1),(-1,1)]       # black pawn at (r-1,c±1) attacks (r,c)
    else:
        P, N, Bq, Rq, K = "P", "N", "[BQ]", "[RQ]", "K"
        pdirs = [(1,-1),(1,1)]
    alts = []
    def at(rr, cc, ch):
        return "^.{%d}%s" % (1+I(rr,cc), ch)
    for dr, dc in pdirs:
        if inb(r+dr, c+dc): alts.append(at(r+dr, c+dc, P))
    for dr, dc in [(1,2),(2,1),(-1,2),(-2,1),(1,-2),(2,-1),(-1,-2),(-2,-1)]:
        if inb(r+dr, c+dc): alts.append(at(r+dr, c+dc, N))
    for dr in (-1,0,1):
        for dc in (-1,0,1):
            if (dr or dc) and inb(r+dr, c+dc): alts.append(at(r+dr, c+dc, K))
    for dirs, ch in (([(1,1),(1,-1),(-1,1),(-1,-1)], Bq), ([(1,0),(-1,0),(0,1),(0,-1)], Rq)):
        for dr, dc in dirs:
            k = 1
            while inb(r+dr*k, c+dc*k):
                # attacker at distance k, squares between empty
                tr, tc = r+dr*k, c+dc*k
                # build regex in index order
                sq = {I(r+dr*j, c+dc*j): "\\." for j in range(1, k)}
                sq[I(tr, tc)] = ch
                items = sorted(sq.items())
                s = "^"; pos = -1
                s = "^."  # tag
                pos = 0
                for i, ch_ in items:
                    if i - pos: s += ".{%d}" % (i - pos)
                    s += ch_
                    pos = i + 1
                alts.append(s)
                k += 1
    return alts
