import json, re

pairs = []
def add(p, r): pairs.append([p, r])

def I(r, c): return 9 * r + c   # r=0 is rank 8; board-relative index
def inb(r, c): return 0 <= r < 8 and 0 <= c < 8
FILES = "abcdefgh"
NB = "[.pnbrqk]"
BP = "[pnbrqk]"
EM = "\\."

# Line: TAG + board(71) + " " + side + " " + castling + " " + ep
# ep is digit-free internally: '-' | file+'S' (rank 6) in input; file+'T' (rank 3) in output.

# ---------- 0. normalise ----------
add(r"^(\S+) \S+ (\S+) (\S+).*$", r"O\1 w \2 \3")
add(r" ([a-h])6$", r" \1S")
for n in range(8, 0, -1):
    add(str(n), "." * n)

def build(changes, ep_new="-", ep_lit=None, tag_to="N", gate=""):
    """changes: {boardindex: (required regex, replacement text)}.
    Emits the original line followed by a new line."""
    items = sorted(changes.items())
    pat = "(?m)^O" + gate
    rn = tag_to
    pos = 0; g = 1
    for i, (req, new) in items:
        if i - pos:
            pat += "(.{%d})" % (i - pos); rn += "\\%d" % g; g += 1
        pat += "(%s)" % req; rn += new; g += 1
        pos = i + 1
    if 71 - pos:
        pat += "(.{%d})" % (71 - pos); rn += "\\%d" % g; g += 1
    pat += " w (\\S+) " + (ep_lit if ep_lit else "\\S+") + "$"
    rn += " b \\%d %s" % (g, ep_new)
    return pat, "\\g<0>\n" + rn

def mv(frm, to, req_from, req_to, new_to=None, **kw):
    ch = {I(*frm): (req_from, "."), I(*to): (req_to, new_to or req_from)}
    return build(ch, **kw)

# ---------- 1. pseudo-legal moves ----------
for r in range(8):
    for c in range(8):
